class Solution {
    public int numSpecialEquivGroups(String[] words){
        Set<String> signatures=new HashSet<>();
        for(String word:words){
            char[] even=new char[(word.length()+1)/2],odd=new char[word.length()/2];
            for(int i=0;i<word.length();i++)if(i%2==0)even[i/2]=word.charAt(i);
            else odd[i/2]=word.charAt(i);
            Arrays.sort(even);
            Arrays.sort(odd);
            signatures.add(new String(even)+"#"+new String(odd));
        }
        return signatures.size();
    }
}

code.kotlin:
class Solution {
    fun numSpecialEquivGroups(words:Array<String>):Int=words.map{
        word->val even=word.filterIndexed{
            index,_->index%2==0
        }.toCharArray().sorted().joinToString("");
        val odd=word.filterIndexed{
            index,_->index%2==1
        }.toCharArray().sorted().joinToString("");
        "$even#$odd"
    }.toSet().size
}

code.cpp:
class Solution {
    public: int numSpecialEquivGroups(vector<string>& words){
        unordered_set<string> signatures;
        for(string& word:words){
            string even,odd;
            for(int i=0;i<(int)word.size();++i)(i%2?odd:even)+=word[i];
            sort(even.begin(),even.end());
            sort(odd.begin(),odd.end());
            signatures.insert(even+"#"+odd);
        }
        return signatures.size();
    }
};
